import without_replacement_size_principle as m
from scipy.special import logsumexp, expit
from scipy.optimize import minimize
d=pd.read_csv('responses.csv')
sets=[tuple(int(x) for x in s.split(',')) for s in d.number_set]
uniq=list(dict.fromkeys(sets)); idx={s:i for i,s in enumerate(uniq)}
