    out=[]
    for ex in uniq:
        tot=np.zeros(len(M)); sh=np.zeros(len(M))
        for x in ex:
            mem=M[:,x-1]; rem=np.maximum(S-sh,1)
            tot+=np.log(alpha*mem/rem**expo+(1-alpha)/100); sh+=mem
        out.append(tot)
    return np.array(out)
