    lp=L+logprior; lp-=logsumexp(lp,1,keepdims=True)
    P=np.exp(lp)@M
    return P[si,tg]
def nll(p,lapse,g):
    p=(1-lapse)*p+lapse*g; p=np.clip(p,1e-9,1-1e-9)
    return -(y*np.log(p)+(1-y)*np.log(1-p)).sum()
NI=len(M)-NR
def base_prior(lam):
    return np.where(isrule,np.log(lam/NR),np.log((1-lam)/NI))
variants={}
def v_inc(t): lam,la,g=expit(t[:3]); return nll(pred(L0,base_prior(lam)),la,g)
def v_digit(t):
    lam,la,g,w=expit(t[:4]); lp=base_prior(lam)+np.where(digit,np.log(w),np.where(isrule,np.log(1-w),0))
    lp[isrule]+=np.log(NR)-np.where(digit,np.log(20),np.log(NR-20))[isrule]
    return nll(pred(L0,lp),la,g)
def v_intpow(t):
    lam,la,g=expit(t[:3]); k=t[3]; lp=np.where(isrule,0,-k*logS); lp[~isrule]-=logsumexp(lp[~isrule]); lp[~isrule]+=np.log(1-lam); lp[isrule]=np.log(lam/NR)
    return nll(pred(L0,lp),la,g)
def v_expo(t):
    lam,la,g=expit(t[:3]); return nll(pred(LL(0.9,np.exp(t[3])),base_prior(lam)),la,g)
for name,f,x0 in [('inc',v_inc,[0,-3,0]),('digitshare',v_digit,[0,-3,0,-1]),('intpow',v_intpow,[0,-3,0,0]),('expo',v_expo,[0,-3,0,0])]:
    r=minimize(f,x0,method='Nelder-Mead',options={'maxiter':800,'xatol':1e-4,'fatol':1e-4}); print(name,r.fun,r.x)
